<?php
if (!defined('ABSPATH')) { exit; }
/** Réception idempotente des opérations hors ligne. */
final class FKC_Sync_Push_API {
 private static function t($n){global $wpdb;return in_array($n,array('users','tenants','branches','members','permissions','branch_access','invitations','audit_logs','sessions'),true)?'bta_'.$n:$wpdb->prefix.'bta_'.$n;}
 private static function err($c,$m,$s=400){return new WP_Error($c,$m,array('status'=>$s));}
 public static function boot(){add_action('init',array(__CLASS__,'install'),5);add_action('rest_api_init',array(__CLASS__,'routes'));}
 public static function install(){global $wpdb;$table=self::t('sync_operations');$charset=$wpdb->get_charset_collate();require_once ABSPATH.'wp-admin/includes/upgrade.php';$sql="CREATE TABLE {$table} (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
 tenant_id BIGINT UNSIGNED NOT NULL,
 operation_id CHAR(36) NOT NULL,
 operation_type VARCHAR(40) NOT NULL,
 payload_hash CHAR(64) NOT NULL,
