 public static function routes(){register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/sync/push',array('methods'=>'POST','callback'=>array(__CLASS__,'push'),'permission_callback'=>'__return_true'));register_rest_route('bta/v1','/tenants/(?P<tenant_id>\d+)/sync/operations/(?P<operation_id>[0-9a-fA-F-]{36})',array('methods'=>'GET','callback'=>array(__CLASS__,'status'),'permission_callback'=>'__return_true'));}
 public static function status($r){$tenant=absint($r['tenant_id']);$user=self::user($r,$tenant);if(is_wp_error($user))return $user;$id=strtolower(trim((string)$r['operation_id']));if(!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/',$id))return self::err('bta_invalid_operation_id','Identifiant UUID invalide.');global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT operation_id,operation_type,status,response,error_code,error_message,created_by,created_at,completed_at FROM '.self::t('sync_operations').' WHERE tenant_id=%d AND operation_id=%s LIMIT 1',$tenant,$id),ARRAY_A);if(!$row || (int)$row['created_by'] !== (int)$user)return self::err('bta_sync_operation_not_found','Opération introuvable.',404);if($row['status']==='PROCESSING' && strtotime($row['created_at'].' UTC') < time()-900){$wpdb->update(self::t('sync_operations'),array('status'=>'REVIEW','error_code'=>'bta_sync_interrupted','error_message'=>'Traitement interrompu ou délai dépassé; vérification manuelle requise.','updated_at'=>gmdate('Y-m-d H:i:s')),array('tenant_id'=>$tenant,'operation_id'=>$id,'status'=>'PROCESSING'));$row['status']='REVIEW';$row['error_code']='bta_sync_interrupted';$row['error_message']='Traitement interrompu ou délai dépassé; vérification manuelle requise.';}$response=$row['response']?json_decode($row['response'],true):null;if(is_array($response)&&$row['status']==='DONE')$response['operation_id']=$id;return array('success'=>true,'operation_id'=>$row['operation_id'],'type'=>$row['operation_type'],'status'=>$row['status'],'result'=>is_array($response)?$response:null,'error'=> $row['error_code'] ? array('code'=>$row['error_code'],'message'=>$row['error_message']) : null,'created_at'=>$row['created_at'],'completed_at'=>$row['completed_at']);}
 private static function user($r,$tenant){$h=$r->get_header('authorization');if(!$h&&isset($_SERVER['HTTP_AUTHORIZATION']))$h=wp_unslash($_SERVER['HTTP_AUTHORIZATION']);if(!is_string($h)||!preg_match('/^Bearer\s+([a-fA-F0-9]{64})$/',$h,$m))return self::err('bta_unauthenticated','Connexion requise.',401);global $wpdb;$s=$wpdb->get_row($wpdb->prepare('SELECT s.user_id,u.status FROM '.self::t('sessions').' s JOIN '.self::t('users').' u ON u.id=s.user_id WHERE s.token_hash=%s AND s.expires_at>%s LIMIT 1',hash('sha256',$m[1]),gmdate('Y-m-d H:i:s')),ARRAY_A);if(!$s||$s['status']!=='ACTIVE')return self::err('bta_unauthenticated','Session invalide ou expirée.',401);$member=$wpdb->get_row($wpdb->prepare("SELECT role FROM ".self::t('members')." WHERE tenant_id=%d AND user_id=%d AND status='ACTIVE' LIMIT 1",$tenant,$s['user_id']),ARRAY_A);if(!$member)return self::err('bta_forbidden','Accès refusé.',403);return (int)$s['user_id'];}
 public static function push($r){$tenant=absint($r['tenant_id']);$user=self::user($r,$tenant);if(is_wp_error($user))return $user;$id=strtolower(trim((string)$r->get_param('operation_id')));$type=sanitize_key((string)$r->get_param('type'));$payload=$r->get_param('payload');if(!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/',$id)||!in_array($type,array('stock_adjustment','sale_create','purchase_create','expense_create','debt_payment','sale_refund','category_create','category_update','product_create','product_update','product_archive','customer_create','customer_update','supplier_create','supplier_update'),true)||!is_array($payload))return self::err('bta_invalid_sync_operation','operation_id UUID, type d’opération reconnu et payload objet requis.');$access=FKC_Branch_Access::guard(null,null,$r);if(is_wp_error($access))return $access;$hash=hash('sha256',wp_json_encode(array('type'=>$type,'payload'=>$payload)));global $wpdb;$table=self::t('sync_operations');$existing=$wpdb->get_row($wpdb->prepare("SELECT payload_hash,status,response,created_by,created_at FROM {$table} WHERE tenant_id=%d AND operation_id=%s",$tenant,$id),ARRAY_A);if($existing){if((int)$existing['created_by'] !== (int)$user)return self::err('bta_sync_id_conflict','Identifiant déjà utilisé.',409);if(!hash_equals($existing['payload_hash'],$hash))return self::err('bta_sync_id_conflict','Cet identifiant existe avec un contenu différent.',409);if($existing['status']==='DONE'){$out=json_decode($existing['response'],true);if(!is_array($out))$out=array('success'=>true);$out['operation_id']=$id;$out['duplicate']=true;return new WP_REST_Response($out,200);}if($existing['status']==='FAILED')return self::err('bta_sync_previous_failure','Cette opération a déjà échoué; corrigez les données et utilisez un nouvel UUID.',409);if($existing['status']==='REVIEW')return self::err('bta_sync_manual_review','Cette opération nécessite une vérification avant toute nouvelle tentative.',409);if($existing['status']==='PROCESSING' && strtotime($existing['created_at'].' UTC') < time()-900){$wpdb->update($table,array('status'=>'REVIEW','error_code'=>'bta_sync_interrupted','error_message'=>'Traitement interrompu ou délai dépassé; vérification manuelle requise.','updated_at'=>gmdate('Y-m-d H:i:s')),array('tenant_id'=>$tenant,'operation_id'=>$id,'status'=>'PROCESSING'));return self::err('bta_sync_manual_review','Cette opération nécessite une vérification avant toute nouvelle tentative.',409);}return self::err('bta_sync_in_progress','Cette opération est déjà en traitement.',409);}
 $ok=$wpdb->insert($table,array('tenant_id'=>$tenant,'operation_id'=>$id,'operation_type'=>$type,'payload_hash'=>$hash,'status'=>'PROCESSING','created_by'=>$user,'created_at'=>gmdate('Y-m-d H:i:s'),'updated_at'=>gmdate('Y-m-d H:i:s')));if(!$ok){return self::err('bta_sync_id_conflict','Identifiant déjà utilisé ou stockage indisponible.',409);}
 $result=FKC_Sync_Adapters::dispatch($r,$tenant,$type,$payload);if($result===null){if($type==='stock_adjustment'){$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/stock/adjustments');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('branch_id','product_id','quantity_delta','reason','expected_quantity') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$result=FKC_Stock_Ops_API::adjust($sub);}elseif($type==='sale_create'){$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/sales');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('branch_id','customer_id','reference','currency','exchange_rate','items','discount','paid','payment_method','payment_reference','notes') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$result=FKC_Sales_API::sale_create($sub);}elseif($type==='purchase_create'){$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/purchases');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('branch_id','supplier_id','preorder_id','reference','currency','exchange_rate','items','fees','paid','payment_method','payment_reference','notes') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$result=FKC_Purchases_API::purchase_create($sub);}elseif($type==='expense_create'){$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/expenses');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('branch_id','category','description','amount','currency','exchange_rate','payment_method','receipt_url') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$result=FKC_Sales_API::expense_create($sub);}elseif($type==='debt_payment'){$debt_id=absint($payload['debt_id']??0);if(!$debt_id){$now=gmdate('Y-m-d H:i:s');$wpdb->update($table,array('status'=>'FAILED','error_code'=>'bta_invalid_sync_payload','error_message'=>'debt_id requis pour debt_payment.','response'=>wp_json_encode(array('status'=>400)),'updated_at'=>$now,'completed_at'=>$now),array('tenant_id'=>$tenant,'operation_id'=>$id,'created_by'=>$user));return self::err('bta_invalid_sync_payload','debt_id requis pour debt_payment.');}$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/debts/'.$debt_id.'/payments');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('amount','method','reference') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$sub->set_param('debt_id',$debt_id);$result=FKC_Sales_API::debt_payment($sub);}else{$sale_id=absint($payload['sale_id']??0);if(!$sale_id){$now=gmdate('Y-m-d H:i:s');$wpdb->update($table,array('status'=>'FAILED','error_code'=>'bta_invalid_sync_payload','error_message'=>'sale_id requis pour sale_refund.','response'=>wp_json_encode(array('status'=>400)),'updated_at'=>$now,'completed_at'=>$now),array('tenant_id'=>$tenant,'operation_id'=>$id,'created_by'=>$user));return self::err('bta_invalid_sync_payload','sale_id requis pour sale_refund.');}$sub=new WP_REST_Request('POST','/bta/v1/tenants/'.$tenant.'/sales/'.$sale_id.'/refunds');$sub->set_param('tenant_id',$tenant);$sub->set_header('Authorization',$r->get_header('authorization'));foreach(array('amount','method','reference','notes') as $key){if(array_key_exists($key,$payload))$sub->set_param($key,$payload[$key]);}$sub->set_param('sale_id',$sale_id);$result=FKC_Refunds_API::create_refund($sub);}}if(is_wp_error($result)){$ed=$result->get_error_data();$status=is_array($ed)&&isset($ed['status'])?(int)$ed['status']:400;$wpdb->update($table,array('status'=>'FAILED','error_code'=>$result->get_error_code(),'error_message'=>$result->get_error_message(),'response'=>wp_json_encode(array('status'=>$status)),'updated_at'=>gmdate('Y-m-d H:i:s'),'completed_at'=>gmdate('Y-m-d H:i:s')),array('tenant_id'=>$tenant,'operation_id'=>$id));return $result;}$data=$result instanceof WP_REST_Response?$result->get_data():$result;$data['operation_id']=$id;$data['duplicate']=false;$wpdb->update($table,array('status'=>'DONE','response'=>wp_json_encode($data),'updated_at'=>gmdate('Y-m-d H:i:s'),'completed_at'=>gmdate('Y-m-d H:i:s')),array('tenant_id'=>$tenant,'operation_id'=>$id));$data['operation_id']=$id;$data['duplicate']=false;return new WP_REST_Response($data,201);
 }
}
